"""Test suite for click.decorators module."""

import pytest


class TestPassContext:
    """Tests for pass_context decorator."""

    def test_pass_context_basic(self):
        """Test basic pass_context functionality."""
        from click import pass_context, Context

        @pass_context
        def callback(ctx, value):
            return ctx, value

        # This should work when invoked within a context
        assert callable(callback)

    def test_pass_context_with_args(self):
        """Test pass_context with arguments."""
        from click import pass_context, Context

        @pass_context
        def callback(ctx, arg1, arg2=None):
            return (ctx, arg1, arg2)

        assert callable(callback)

    def test_pass_context_returns_callable(self):
        """Test that pass_context returns a proper wrapper."""
        from click import pass_context

        @pass_context
        def my_callback(ctx):
            return "result"

        # Verify it's a proper function wrapper
        assert hasattr(my_callback, '__wrapped__') or callable(my_callback)


