class TestMakePassDecorator:
    """Tests for make_pass_decorator function."""

    def test_make_pass_decorator_create(self):
        """Test creating a custom pass decorator."""
        from click import make_pass_decorator, Context

        decorator = make_pass_decorator(Context)
        assert callable(decorator)

    def test_make_pass_decorator_with_ensure(self):
        """Test make_pass_decorator with ensure=True."""
        from click import make_pass_decorator, Context

        decorator = make_pass_decorator(Context, ensure=True)
        assert callable(decorator)

    def test_make_pass_decorator_raises_no_context(self):
        """Test that make_pass_decorator raises RuntimeError without context."""
        from click import make_pass_decorator, Context

        decorator = make_pass_decorator(Context)

        @decorator
        def callback(obj):
            return obj

        # Try to invoke without context - should raise RuntimeError
        with pytest.raises(RuntimeError) as exc_info:
            callback()

        # The error message may vary between versions
        assert "context" in str(exc_info.value).lower() or "Managed to invoke callback" in str(exc_info.value)

    def test_make_pass_decorator_with_ensure_true(self):
        """Test make_pass_decorator with ensure=True creates object."""
        from click import make_pass_decorator, Context

        decorator = make_pass_decorator(dict, ensure=True)

        @decorator
        def callback(obj):
            return isinstance(obj, dict)

        # When used within a context with ensure=True, should create object
        # This tests the ensure=True code path
        assert callable(callback)

    def test_make_pass_decorator_runtime_error_message(self):
        """Test that RuntimeError has correct message format."""
        from click import make_pass_decorator, Context

        decorator = make_pass_decorator(Context)

        @decorator
        def callback(obj):
            return obj

        # Try to invoke without context - should raise RuntimeError
        with pytest.raises(RuntimeError) as exc_info:
            callback()

        # Check for specific error message components
        error_msg = str(exc_info.value).lower()
        assert "context" in error_msg


