class TestIntegration:
    """Integration tests for decorators."""

    def test_combined_decorators(self):
        """Test combining multiple decorators."""
        from click import command, option, argument

        @command()
        @option("--verbose", is_flag=True)
        @argument("name")
        def combined_cmd(name, verbose):
            return {"name": name, "verbose": verbose}

        assert callable(combined_cmd)
        assert hasattr(combined_cmd, 'params')

    def test_nested_commands(self):
        """Test nested command structure."""
        from click import group, command

        @group()
        def cli():
            """Main CLI."""
            pass

        @cli.command()
        def subcommand():
            """Subcommand."""
            pass

        assert cli is not None
        assert hasattr(cli, 'commands')

    def test_command_with_all_option_types(self):
        """Test command with various option types."""
        import click
        from click import command, option

        @command()
        @option("--flag", is_flag=True)
        @option("--count", type=int, default=1)
        @option("--name", help="Name parameter")
        @option("--path", type=click.Path())
        def multi_opt(flag, count, name, path):
            return locals()

        assert callable(multi_opt)

    def test_full_cli_structure(self):
        """Test a full CLI structure with multiple commands."""
        from click import group, command, option

        @group()
        def cli():
            """Main CLI application."""
            pass

        @cli.command()
        @option("--output", "-o", help="Output file")
        def process(output):
            """Process data."""
            return output

        @cli.command()
        @option("--verbose", "-v", is_flag=True)
        def analyze(verbose):
            """Analyze data."""
            return verbose

        assert cli is not None
        assert 'process' in cli.commands
        assert 'analyze' in cli.commands

    def test_command_with_both_params_and_decorators(self):
        """Test command with both params argument and decorated params."""
        from click import command, option

        @command(params=["input_file"])
        @option("--output", "-o")
        def cmd(input_file, output):
            return input_file, output

        assert callable(cmd)
        assert len(cmd.params) >= 2

