class TestIdentity:
    """Tests for identity function."""

    def test_identity_returns_argument(self):
        from jinja2.runtime import identity
        assert identity(42) == 42
        assert identity("hello") == "hello"
        assert identity(None) is None
        assert identity([1, 2, 3]) == [1, 2, 3]


class TestMarkupJoin:
    """Tests for markup_join function."""

    def test_markup_join_simple(self):
        from jinja2.runtime import markup_join
        result = markup_join(["a", "b", "c"])
        assert result == "abc"

    def test_markup_join_with_html(self):
        from markupsafe import Markup
        from jinja2.runtime import markup_join
        result = markup_join([Markup("<b>hello</b>"), " ", Markup("<i>world</i>")])
        assert isinstance(result, Markup)
        assert "<b>hello</b>" in str(result)

    def test_markup_join_empty(self):
        from jinja2.runtime import markup_join
        result = markup_join([])
        assert result == ""

    def test_markup_join_with_numbers(self):
        from jinja2.runtime import markup_join
        result = markup_join([1, 2, 3])
        assert result == "123"


