        for item, loop_ctx in loop:
            if first_iteration:
                # previtem should be an Undefined instance on first iteration
                assert isinstance(loop_ctx.previtem, Undefined)
                first_iteration = False
            else:
                assert not isinstance(loop_ctx.previtem, Undefined)
                break

