        from jinja2.loaders import FileSystemLoader

        # Create a symlink
        link_path = os.path.join(self.templates_dir, "link.html")
        try:
            os.symlink(os.path.join(self.templates_dir, "test.html"), link_path)
            loader = FileSystemLoader(self.templates_dir, followlinks=True)
            templates = loader.list_templates()
            assert "test.html" in templates
        except OSError:
            # Symlinks may not work on all systems
            pass

    def test_filesystem_loader_list_templates_subdirectory(self):
