class TestPeekFilelikeLength:
    """Tests for peek_filelike_length function."""

    def test_peek_filelike_length_real_file(self):
        from httpx._utils import peek_filelike_length
        with tempfile.NamedTemporaryFile(mode='w', delete=False) as f:
            f.write("hello world")
            temp_path = f.name
        try:
            with open(temp_path, 'rb') as f:
                length = peek_filelike_length(f)
                assert length == 11
        finally:
            os.unlink(temp_path)

    def test_peek_filelike_length_bytesio(self):
        from httpx._utils import peek_filelike_length
        stream = io.BytesIO(b"hello world")
        length = peek_filelike_length(stream)
        assert length == 11

    def test_peek_filelike_length_no_fileno(self):
        from httpx._utils import peek_filelike_length
        class NoFilenoStream:
            def fileno(self):
                raise AttributeError("No file descriptor")
            def tell(self):
                return 0
            def seek(self, pos, whence=0):
                raise OSError("Cannot seek")
        stream = NoFilenoStream()
        length = peek_filelike_length(stream)
        assert length is None

    def test_peek_filelike_length_seek_error(self):
        from httpx._utils import peek_filelike_length
        class SeekErrorStream:
            def fileno(self):
                raise OSError("No file descriptor")
            def tell(self):
                return 0
            def seek(self, pos, whence=0):
                raise OSError("Cannot seek")
        stream = SeekErrorStream()
        length = peek_filelike_length(stream)
        assert length is None


