        from pydantic import BaseModel, ConfigDict
        from pydantic.fields import FieldInfo

        def field_title_generator(field_name, field_info):
            return f'Title_{field_name}'

        class Model(BaseModel):
            model_config = ConfigDict(field_title_generator=field_title_generator)
            my_field: str

        schema = Model.model_json_schema()
        assert schema['properties']['my_field'].get('title') == 'Title_my_field'

    def test_deprecate_warning_on_keyword_config(self):
        """Test deprecation warning when passing config as keyword argument."""
        import warnings
        from pydantic.config import with_config

        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")

            @with_config(config={'frozen': True})
            class MyClass:
                pass

            # Check that a deprecation warning was issued
            assert len(w) >= 1
            assert any('deprecated' in str(warning.message).lower() for warning in w)

