        """Test WrapSerializer that just passes through using handler."""
        from pydantic import BaseModel, WrapSerializer
        from typing_extensions import Annotated

        def identity_wrapper(value: Any, handler, info) -> Any:
            return handler(value)

        WrappedType = Annotated[list, WrapSerializer(identity_wrapper)]

        class Model(BaseModel):
            data: WrappedType

        m = Model(data=[1, 2, 3])
        result = m.model_dump()
        assert result == {'data': [1, 2, 3]}

    def test_field_serializer_returns_different_type(self):
        """Test field_serializer that returns different type than input."""
        from pydantic import BaseModel, field_serializer

        class Model(BaseModel):
            value: int

            @field_serializer('value')
            def serialize_value(self, v: int) -> str:
                return f"value_{v}"

        m = Model(value=5)
        result = m.model_dump()
        assert result == {'value': 'value_5'}

    def test_model_serializer_returns_dict(self):
        """Test model_serializer that returns dict."""
        from pydantic import BaseModel, model_serializer

        class Model(BaseModel):
            x: int
            y: int

            @model_serializer()
            def serialize_model(self):
                return {'sum': self.x + self.y}

        m = Model(x=3, y=4)
        result = m.model_dump()
        assert result == {'sum': 7}

