class TestCookieParser:
    def test_cookie_parser_basic(self):
        from starlette.requests import cookie_parser
        result = cookie_parser("name=value")
        assert result == {"name": "value"}

    def test_cookie_parser_multiple_cookies(self):
        from starlette.requests import cookie_parser
        result = cookie_parser("name1=value1; name2=value2")
        assert result == {"name1": "value1", "name2": "value2"}

    def test_cookie_parser_empty_value(self):
        from starlette.requests import cookie_parser
        result = cookie_parser("name=")
        assert result == {"name": ""}

    def test_cookie_parser_no_equals(self):
        from starlette.requests import cookie_parser
        result = cookie_parser("name")
        assert result == {"": "name"}

    def test_cookie_parser_whitespace(self):
        from starlette.requests import cookie_parser
        result = cookie_parser("  name  =  value  ")
        assert result == {"name": "value"}

    def test_cookie_parser_special_chars(self):
        from starlette.requests import cookie_parser
        result = cookie_parser("name=%2F%3D")
        # Cookie parser doesn't decode URL-encoded values
        assert result == {"name": "%2F%3D"}


