    @pytest.mark.anyio
    async def test_request_stream_returns_body(self):
        from starlette.requests import Request
        scope = {"type": "http"}
        received_messages = [
            {"type": "http.request", "body": b"hello"},
            {"type": "http.request", "body": b" world", "more_body": False},
        ]
        async def mock_receive():
            return received_messages.pop(0) if received_messages else {"type": "http.disconnect"}
        request = Request(scope, receive=mock_receive)
        chunks = []
        async for chunk in request.stream():
            chunks.append(chunk)
        assert b"hello" in b"".join(chunks)

    @pytest.mark.anyio
    async def test_request_stream_consumed_raises(self):
        from starlette.requests import Request
        scope = {"type": "http"}
        received_messages = [
            {"type": "http.request", "body": b"test"},
            {"type": "http.request", "more_body": False},
        ]
        async def mock_receive():
            return received_messages.pop(0) if received_messages else {"type": "http.disconnect"}
        request = Request(scope, receive=mock_receive)
        # First consume the stream
        async for _ in request.stream():
            pass
        # Second consumption should raise RuntimeError
        with pytest.raises(RuntimeError):
            async for _ in request.stream():
                pass

